test:
// pysssss.StringFunction — `this.widgets.length = pos` truncation, plus the
// ComfyWidgets["STRING"] + inputEl.readOnly readout it rebuilds each execution.
//
// Run this file against BOTH the original and the converted source.
//
//   equivalence  must pass on both — the conversion changed no behaviour
//   fix          must FAIL on the original and PASS on the converted source
//
// equivalence: executing renders message.text into a widget named "result",
//              and re-executing replaces that widget rather than appending.
// fix:         the readout is non-editable through the published `disabled`
//              property. The original faked it with `inputEl.readOnly`, a
//              deprecated alias for `element` that the Vue node renderer never
//              consults — so the textarea stayed editable under Nodes 2.0.
import { beforeAll, describe, expect, it } from 'vitest'

import { LGraph } from '@/lib/litegraph/src/LGraph'
import { LGraphNode } from '@/lib/litegraph/src/LGraphNode'
import { applyDefExtensions, useComfyApi } from '@/platform/nodeApi/comfyApi'
import { useCanvasStore } from '@/renderer/core/canvas/canvasStore'
import { app } from '@/scripts/app'
import { useExtensionStore } from '@/stores/extensionStore'

const TYPE = 'StringFunction|pysssss'
const DEF = {
  name: TYPE,
  display_name: 'String Function',
  category: 'utils/string',
  output: ['STRING'],
  output_name: ['STRING'],
  input: { required: {} }
}

class StringFunction extends LGraphNode {
  constructor() {
    super(TYPE)
  }
}

const graph = new LGraph()

beforeAll(async () => {
  // Both dispatch paths run: the original registered a legacy
  // `beforeRegisterNodeDef`, the converted source a `comfy.defs.extend`. Only
  // one of them has anything to apply, so this file is source-agnostic.
  useCanvasStore().currentGraph = graph
  useComfyApi(() => graph)
  for (const extension of useExtensionStore().extensions) {
    await extension.beforeRegisterNodeDef?.(
      StringFunction as never,
      DEF as never,
      app
    )
  }
  applyDefExtensions(StringFunction, DEF)
})

function newNode(): LGraphNode {
  const node = new StringFunction()
  graph.add(node)
  return node
}

const execute = (node: LGraphNode, text: string[]) =>
  node.onExecuted?.({ text } as never)

const resultWidget = (node: LGraphNode) =>
  node.widgets?.find((w) => w.name === 'result')

describe('pysssss.StringFunction', () => {
  describe('equivalence — must pass before and after', () => {
    it('renders the executed text into a "result" widget', () => {
      const node = newNode()
      const text = ['hello world']
      execute(node, text)

      expect(resultWidget(node)?.value).toBe(text)
    })

    it('replaces the readout instead of appending one per execution', () => {
      const node = newNode()
      execute(node, ['first'])
      execute(node, ['second'])
      execute(node, ['third'])

      expect(node.widgets?.filter((w) => w.name === 'result')).toHaveLength(1)
      expect(resultWidget(node)?.value).toEqual(['third'])
    })

    it('drops every widget from "result" onwards, keeping earlier ones', () => {
      const node = newNode()
      node.addWidget('string', 'keep_me', 'a', () => {})
      execute(node, ['x'])
      node.addWidget('string', 'trailing', 'b', () => {})
      execute(node, ['y'])

      expect(node.widgets?.map((w) => w.name)).toEqual(['keep_me', 'result'])
    })
  })

  describe('fix — must fail before, pass after', () => {
    it('marks the readout disabled rather than faking read-only on inputEl', () => {
      const node = newNode()
      execute(node, ['x'])

      expect(resultWidget(node)?.disabled).toBe(true)
    })
  })
})
